{
  "root_causes": [
    {
      "service": "reservation",
      "fault_kind": "container_cpu_saturated",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT service_name, attr_k8s_pod_name, round(avg(value),2) AS avg_cpu, round(min(value),2) AS min_cpu, round(max(value),2) AS max_cpu FROM abnormal_metrics WHERE service_name='reservation' AND metric='container.cpu.usage' GROUP BY 1,2",
          "claim": "Reservation container CPU is pinned near 3.77 cores in the incident window (avg 1.89), versus about 0.01 cores in the normal period."
        },
        {
          "kind": "metric",
          "sql": "SELECT src, service_name, round(avg(value),3) AS avg_cpu FROM (SELECT 'abnormal' src, * FROM abnormal_metrics UNION ALL SELECT 'normal', * FROM normal_metrics) WHERE service_name='reservation' AND metric='container.cpu.usage' GROUP BY 1,2 ORDER BY 1",
          "claim": "Reservation average container CPU rises from about 0.01 cores in normal to about 1.9 cores in the abnormal period."
        },
        {
          "kind": "trace",
          "sql": "SELECT strftime(time,'%H:%M') t, service_name, span_name, count(*) n, round(quantile_cont(duration,0.95)/1e6,2) p95_ms FROM abnormal_traces WHERE service_name='reservation' AND span_name LIKE 'reservation.Reservation/CheckAvailability' GROUP BY 1,2,3 ORDER BY 1",
          "claim": "Reservation CheckAvailability spans keep running throughout the saturated window, with no error status and p95 of about 4.8 ms, close to normal."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "reservation",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "WITH cl AS (SELECT 'a' src, * FROM abnormal_traces WHERE service_name='frontend' AND attr_span_kind='Client' AND span_name LIKE 'reservation.%' UNION ALL SELECT 'n', * FROM normal_traces WHERE service_name='frontend' AND attr_span_kind='Client' AND span_name LIKE 'reservation.%'), sv AS (SELECT 'a' src, * FROM abnormal_traces WHERE service_name='reservation' AND attr_span_kind='Server' UNION ALL SELECT 'n', * FROM normal_traces WHERE service_name='reservation' AND attr_span_kind='Server') SELECT cl.src, count(*) n, round(quantile_cont(cl.duration,0.95)/1e6,2) frontend_client_p95_ms, round(quantile_cont(sv.duration,0.95)/1e6,2) reservation_server_p95_ms FROM cl JOIN sv ON sv.parent_span_id = cl.span_id AND sv.src=cl.src GROUP BY 1 ORDER BY 1",
          "claim": "Frontend's reservation calls run about 4.9 ms p95 against reservation server spans at 4.6 ms, so the caller waits on reservation in the abnormal period."
        }
      ]
    }
  ]
}
